import re
import six
import abc
from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure

__author__ = 'Marcin Usielski'
__copyright__ = 'Copyright (C) 2018-2021, Nokia'
__email__ = 'marcin.usielski@nokia.com'


@six.add_metaclass(abc.ABCMeta)
class GenericEMSSIMCommand(CommandTextualGeneric):
    """Genericemssimcommand command class."""

    _re_default_prompt = re.compile(r"#(F|S)")
    _newline_chars = ("\r", "\n")

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Genericemssimcommand command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        if not prompt:
            prompt = GenericEMSSIMCommand._re_default_prompt
        if not newline_chars:
            newline_chars = GenericEMSSIMCommand._newline_chars
        super(GenericEMSSIMCommand, self).__init__(connection, prompt=prompt, newline_chars=newline_chars,
                                                   runner=runner)
        self.cmd_run_id = None  # String representation
        self._re_prompt = None

    # 10:25:04 [17]    <|env
    _re_start_command_id = re.compile(r"\[(\d+)\]\s+\<\|")

    def _detect_start_of_cmd_output(self, line, is_full_line):
        if is_full_line and self._regex_helper.search(self._cmd_escaped, line) \
                and self._regex_helper.search_compiled(GenericEMSSIMCommand._re_start_command_id, line):
            self._cmd_output_started = True
            self.cmd_run_id = self._regex_helper.group(1)
            self._re_prompt = re.compile(r"\[" + self.cmd_run_id + r"\]\s+>\|#([F|S])")

    def is_end_of_cmd_output(self, line):
        """
        Check end of command output.

        :param line: Line from device.
        :return: None
        """
        if self._regex_helper.search_compiled(self._re_prompt, line):
            if 'F' == self._regex_helper.group(1):
                self.set_exception(CommandFailure(self, '#F returned by EMSSIM.'))
            return True
        return False

    def on_new_line(self, line, is_full_line):
        """
        To parse command output. will be called after line with command echo.

        Write your own implementation but don't forget to call on_new_line from base class.

        :param line: Line to parse, new lines are trimmed
        :param is_full_line:  False for chunk of line; True on full line (NOTE: new line character removed)
        :return: None
        """
        if is_full_line:
            self._extend_timeout_on_emssim_request(line)
        return super(GenericEMSSIMCommand, self).on_new_line(line, is_full_line)

    def _extend_timeout_on_emssim_request(self, line):
        new_timeout = self._emssim_requested_timeout(line)
        if new_timeout:
            self.extend_timeout(new_timeout)

    # *|Match timeout in 2 seconds
    _re_timeout_changed = re.compile(r"\*\|Match timeout in (?P<TIMEOUT>-?\d+) seconds")

    def _emssim_requested_timeout(self, line):
        new_timeout = None
        if self._regex_helper.search_compiled(GenericEMSSIMCommand._re_timeout_changed, line):
            new_timeout = float(self._regex_helper.group("TIMEOUT"))
        return new_timeout
